const img = (id, w = 1400) =>
  `https://images.unsplash.com/photo-${id}?w=${w}&auto=format&fit=crop&q=60`;

// Deterministic per-post fallback used wherever a post would otherwise
// reuse another post's Unsplash photo (or have no image at all). Lorem
// Picsum returns the same real photo for the same seed every time and
// a different photo for every different seed, so keying it off the
// post's slug guarantees every post gets its own image and nothing
// ever 404s.
const imgFor = (seed, w = 1400) =>
  `https://picsum.photos/seed/${seed}/${w}/${Math.round(w * 0.64)}`;

// each post's content is just an array of blocks -- type can be
